library(shiny)
library(bslib)

# =============================================================================
# STAT 3110 - Lecture 20 Lab: Span & Bases
#   Panel 1: build points from a collection of vectors, then place their span
#   Panel 2: find several different bases for the same subspace and compare
#            how one point is identified using each basis
#   Group Notes: everything the group wrote (downloadable)
# Group discussion is built in: a check-in popup, rotating roles, a group
# prediction before every level and a written group answer after every level.
# =============================================================================

lab_css <- r"---(
  body { background-color: #f8fafc; font-family: 'Inter', system-ui, -apple-system, sans-serif; }
  .lab-container { width: 100%; max-width: 1400px; margin: 0 auto; padding: 10px 16px; }
  .level-bar { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px; align-items: center; }
  .lvl-btn {
    border: 1.5px solid #cbd5e1; background: #ffffff; color: #334155;
    padding: 5px 11px; border-radius: 8px; font-weight: 600; font-size: 0.84rem;
    cursor: pointer; display: flex; align-items: center; gap: 5px;
  }
  .lvl-btn:hover { border-color: #64748b; background: #f1f5f9; }
  .lvl-btn.active { background: #1e293b; color: #ffffff; border-color: #1e293b; }
  .lvl-btn.done { border-color: #16a34a; background: #f0fdf4; color: #15803d; }
  .lvl-btn.done.active { background: #15803d; color: #ffffff; border-color: #15803d; }
  .dim-tag { font-size: 0.68rem; padding: 1px 5px; border-radius: 4px; background: #e2e8f0; color: #475569; font-weight: 700; }
  .lvl-btn.active .dim-tag { background: rgba(255,255,255,0.22); color: #fff; }
  .workspace-grid { display: grid; grid-template-columns: 380px minmax(0, 1fr); gap: 16px; align-items: start; }
  @media (max-width: 992px) { .workspace-grid { grid-template-columns: minmax(0, 1fr); } }
  .control-card, .canvas-card {
    background: #ffffff; border-radius: 12px; border: 1px solid #e2e8f0;
    box-shadow: 0 2px 6px rgba(15, 23, 42, 0.04); padding: 16px;
  }
  .canvas-card { padding: 12px; position: relative; min-width: 0; }
  .canvas-wrap { width: 100%; min-width: 0; overflow: hidden; }
  canvas#labCanvas {
    width: 100%; height: 560px; display: block; border-radius: 8px;
    background: #ffffff; border: 1px solid #e2e8f0; touch-action: none;
  }
  .zoom-bar { position: absolute; top: 20px; right: 20px; display: flex; gap: 4px; z-index: 2; }
  .zoom-btn {
    min-width: 32px; height: 32px; border-radius: 6px; border: 1px solid #cbd5e1;
    background: rgba(255,255,255,0.92); color: #1e293b; font-weight: 700; font-size: 1.05rem; cursor: pointer;
  }
  .zoom-btn:hover { background: #f1f5f9; border-color: #64748b; }
  .zoom-reset { font-size: 0.78rem; padding: 0 9px; }
  .role-line {
    font-size: 0.8rem; background: #fefce8; border: 1px solid #fde68a; color: #854d0e;
    border-radius: 8px; padding: 6px 10px; margin-bottom: 10px;
  }
  .stage-badge {
    display: inline-block; padding: 3px 9px; border-radius: 999px; font-size: 0.72rem;
    font-weight: 700; text-transform: uppercase; margin-bottom: 6px; background: #ede9fe; color: #6d28d9;
  }
  .lvl-title { margin-bottom: 4px; font-weight: 700; }
  .lvl-intro { font-size: 0.86rem; color: #475569; margin-bottom: 10px; }
  .status-pill {
    padding: 9px 13px; border-radius: 8px; font-weight: 600; font-size: 0.86rem;
    margin: 10px 0; border: 1.5px solid transparent;
  }
  .pill-neutral { background: #f1f5f9; color: #334155; border-color: #cbd5e1; }
  .pill-success { background: #dcfce7; color: #166534; border-color: #86efac; }
  .pill-danger  { background: #fee2e2; color: #991b1b; border-color: #fca5a5; }
  .pill-warning { background: #fef3c7; color: #92400e; border-color: #fde68a; }
  .readout {
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.8rem;
    background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 8px 10px; margin-bottom: 10px;
  }
  .readout .row-r { display: flex; justify-content: space-between; gap: 8px; padding: 2px 0; border-bottom: 1px dashed #e2e8f0; }
  .readout .row-r:last-child { border-bottom: none; }
  .btn-lab {
    display: block; width: 100%; padding: 9px 14px; border-radius: 8px; font-weight: 600;
    font-size: 0.9rem; border: none; cursor: pointer; margin-top: 8px; text-align: center;
  }
  .btn-lab:disabled { background: #cbd5e1 !important; color: #64748b !important; cursor: not-allowed; }
  .btn-go { background: #2563eb; color: #fff; }
  .btn-go:hover:not(:disabled) { background: #1d4ed8; }
  .btn-alt { background: #7c3aed; color: #fff; }
  .btn-alt:hover:not(:disabled) { background: #6d28d9; }
  .btn-soft { background: #e2e8f0; color: #334155; }
  .btn-soft:hover:not(:disabled) { background: #cbd5e1; }
  .btn-next { background: #16a34a; color: #fff; }
  .btn-next:hover { background: #15803d; }
  .choice-grid { display: flex; flex-direction: column; gap: 6px; margin-top: 6px; }
  .choice {
    text-align: left; padding: 8px 11px; border-radius: 8px; border: 1.5px solid #cbd5e1;
    background: #fff; color: #1e293b; font-size: 0.86rem; cursor: pointer;
  }
  .choice:hover { border-color: #7c3aed; background: #faf5ff; }
  .choice.sel { border-color: #7c3aed; background: #ede9fe; font-weight: 700; }
  .pool-chip {
    display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%;
    padding: 7px 10px; border-radius: 8px; border: 1.5px solid #cbd5e1; background: #fff;
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.84rem; cursor: pointer; margin-top: 6px;
  }
  .pool-chip.sel { background: #eff6ff; border-width: 2.5px; font-weight: 700; }
  .pool-chip .chk { font-family: system-ui, sans-serif; font-size: 0.75rem; color: #64748b; }
  .talk-box {
    background: #fff7ed; border: 1.5px solid #fdba74; color: #7c2d12; border-radius: 10px;
    padding: 10px 12px; font-size: 0.86rem; margin: 10px 0;
  }
  .talk-box .talk-head { font-weight: 800; text-transform: uppercase; font-size: 0.72rem; letter-spacing: 0.04em; color: #c2410c; margin-bottom: 3px; }
  .discuss-card {
    background: #eff6ff; border: 2px solid #60a5fa; color: #1e3a8a; border-radius: 10px; padding: 12px; margin: 10px 0;
  }
  .discuss-card .talk-head { font-weight: 800; text-transform: uppercase; font-size: 0.74rem; letter-spacing: 0.04em; color: #1d4ed8; margin-bottom: 4px; }
  .discuss-card textarea { width: 100%; min-height: 90px; border-radius: 8px; border: 1px solid #93c5fd; padding: 8px; font-size: 0.88rem; margin-top: 8px; }
  .result-box { background: #f0fdf4; border: 1.5px solid #4ade80; color: #166534; border-radius: 10px; padding: 10px 12px; font-size: 0.86rem; margin: 10px 0; }
  .msg-box { background: #fef2f2; border: 1.5px solid #f87171; color: #991b1b; border-radius: 10px; padding: 10px 12px; font-size: 0.86rem; margin: 10px 0; }
  .coord-table { width: 100%; font-size: 0.8rem; border-collapse: collapse; margin-top: 6px; }
  .coord-table th, .coord-table td { border-bottom: 1px solid #e2e8f0; padding: 4px 4px; text-align: left; }
  .help-strip { font-size: 0.79rem; color: #475569; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 8px 12px; margin-top: 10px; }
  .saved-answer { background: #fff; border-left: 4px solid #60a5fa; padding: 6px 10px; font-style: italic; color: #1e293b; margin-top: 6px; }
  #groupBanner { color: #e2e8f0; font-size: 0.82rem; }
  .notes-card { background: #fff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px; margin-bottom: 14px; }
  .notes-table { width: 100%; font-size: 0.86rem; border-collapse: collapse; }
  .notes-table th, .notes-table td { border-bottom: 1px solid #e2e8f0; padding: 6px; vertical-align: top; text-align: left; }
  .def-chip {
    font-size: 0.8rem; background: #f0f9ff; border: 1px solid #bae6fd; color: #075985;
    border-radius: 8px; padding: 6px 10px; margin-bottom: 10px;
  }
  .start-wrap { max-width: 980px; margin: 0 auto; padding: 14px 16px 30px; }
  .start-card { background: #fff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 18px 20px; margin-bottom: 14px; box-shadow: 0 2px 6px rgba(15,23,42,0.04); }
  .start-card h4 { font-weight: 800; margin-bottom: 8px; }
  .start-card .big-def { font-size: 1.02rem; background: #f8fafc; border-left: 4px solid #7c3aed; padding: 8px 12px; margin: 8px 0 10px; }
  .start-card .eg { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.88rem; }
  .start-card ul { margin-bottom: 4px; }
  .start-go { display: inline-block; background: #2563eb; color: #fff; border: none; border-radius: 8px; padding: 10px 18px; font-weight: 700; cursor: pointer; }
  .start-go:hover { background: #1d4ed8; }
)---"

lab_js <- r"---(
(function () {
  'use strict';

  // ===========================================================================
  // CONSTANTS & LEVEL DATA
  // ===========================================================================
  const COLORS = ['#2563eb', '#dc2626', '#16a34a', '#9333ea', '#ea580c', '#0891b2'];
  const VNAMES = ['v1', 'v2', 'v3', 'v4'];
  const PNAMES = ['a', 'b', 'c', 'd', 'e', 'f'];
  const BOX = 4.5;
  const DEFAULT_YAW = -2.3, DEFAULT_PITCH = 0.35, DEFAULT_S3 = 38;
  const SPAN_COLOR = '#7c3aed', OK_COLOR = '#16a34a', V_COLOR = '#2563eb';

  const LEVELS = {
    span: [
      { id: 1, dim: 2, title: 'Level 1: One Vector', vecs: [[2, 1]],
        intro: 'Stretch v1 (drag its arrowhead) to build points. Each time you land somewhere you like, click "Mark this point". Build at least 3 different points, then decide what the span looks like.',
        discuss: 'Every point you built came from stretching v1. In your own words, what does it mean for a point to be "in the span" of v1? Name one point that is NOT in the span.',
        concept: 'The span of one non-zero vector is a line through the origin.' },
      { id: 2, dim: 2, title: 'Level 2: Two Vectors, Different Directions', vecs: [[1, 2], [-2, 1]],
        intro: 'Stretch v1 and v2 and chain them tip-to-tail (drag a shaft so its tail snaps onto the other tip). Mark at least 3 points, then place the span.',
        discuss: 'Pick any spot on the grid. Could your group build it? How would you convince someone, without actually building it?',
        concept: 'Two vectors that point in different directions span the whole plane.' },
      { id: 3, dim: 2, title: 'Level 3: Two Vectors, Same Direction', vecs: [[2, -1], [-4, 2]],
        intro: 'Two vectors again. Build at least 3 points by stretching and chaining, then place the span.',
        discuss: 'You had TWO vectors but the span was smaller than in Level 2. Why? What would you change about v2 so the span becomes the whole plane?',
        concept: 'Collinear vectors only span a line: the second vector adds no new direction.' },
      { id: 4, dim: 2, title: 'Level 4: Three Vectors in 2D', vecs: [[1, 0], [0, 1], [1, 1]],
        intro: 'Three vectors in 2D. Build at least 3 points, then place the span.',
        discuss: 'Did v3 let you reach anything new? Could you delete one vector and keep exactly the same span? Which one(s)?',
        concept: 'Three vectors in the plane span at most the plane. At least one of them is redundant.' },
      { id: 5, dim: 3, title: 'Level 5: One Vector in 3D', vecs: [[1, 1, 2]],
        intro: 'Now in 3D. Drag empty space to rotate the view. Stretch v1 to build at least 3 points, then place the span.',
        discuss: 'How is the span of one vector in 3D the same as in 2D? Is anything different?',
        concept: 'One non-zero vector spans a line through the origin, in 2D or in 3D.' },
      { id: 6, dim: 3, title: 'Level 6: Two Vectors in 3D', vecs: [[2, 0, 1], [0, 2, 1]],
        intro: 'Stretch and chain v1 and v2 to build at least 3 points. Rotate the view to see where your points really are.',
        discuss: 'Your two vectors did not fill all of 3D. Describe a point your group could NOT build, and explain how you know.',
        concept: 'Two non-collinear vectors span a plane through the origin, sitting inside 3D space.' },
      { id: 7, dim: 3, title: 'Level 7: Two Collinear Vectors in 3D', vecs: [[1, 2, 1], [-2, -4, -2]],
        intro: 'Two vectors in 3D. Build at least 3 points, then place the span.',
        discuss: 'Compare this level to Level 6. Both had two vectors in 3D. Why did they span different shapes?',
        concept: 'Two collinear vectors span only a line, even in 3D.' },
      { id: 8, dim: 3, title: 'Level 8: Three Vectors on One Plane', vecs: [[2, 0, 1], [0, 2, 1], [2, 2, 2]],
        intro: 'Three vectors in 3D. Build at least 3 points (try combinations of different vectors), then place the span.',
        discuss: 'Three vectors in 3D, but the span was not all of 3D. Which vector is "extra"? Is there more than one right answer?',
        concept: 'These three vectors are linearly dependent, so together they only span a plane.' },
      { id: 9, dim: 3, title: 'Level 9: Three Vectors in 3D', vecs: [[2, 0, 0], [0, 2, 0], [1, 1, 2]],
        intro: 'Three vectors in 3D. Build at least 3 points (try lifting v3 out of the floor), then place the span.',
        discuss: 'What is the smallest number of vectors that can span all of 3D? Could 4 vectors span it? Could 2? Explain to each other.',
        concept: 'Three linearly independent vectors in 3D span all of 3D.' },
      { id: 10, dim: 3, title: 'Level 10: Four Vectors in 3D', vecs: [[1, 0, 1], [0, 1, 1], [1, 1, 2], [1, -1, 0]],
        intro: 'FOUR vectors in 3D. Build at least 3 points using different combinations, then place the span. Rotate the view before you decide!',
        discuss: 'You had four vectors in 3D, more than you had in Level 9, but the span was only a plane. How can that be? What is the fewest of these vectors you need to span the same plane, and which ones?',
        concept: 'Only d = 2 of these 4 vectors are linearly independent (every one of them lies on the plane z = x + y), so span({v1, v2, v3, v4}) is a 2-dimensional subspace: a plane.' }
    ],
    basis: [
      { id: 1, dim: 2, title: 'Level 1: Bases for All of ℝ²',
        V: { gens: [[1, 0], [0, 1]], kind: 'all', name: 'all of ℝ² (the whole plane)' },
        pool: [[1, 0], [0, 1], [1, 1], [-1, 1], [2, 2]], target: [2, 1], needed: 2,
        intro: 'V is all of ℝ². Pick vectors from the list that form a basis for V and check them. Then identify the point T using your basis: find the coefficients that take you from the origin to T. Do this with 2 different bases (the two bases from lecture are in the list!).',
        discuss: 'Look at your table: the SAME point T was identified with different coefficients in different bases. Which basis made T easiest to describe? Why might someone choose a basis other than {(1, 0), (0, 1)}?',
        concept: 'Basis sets are NOT unique: an infinite number of bases exist for a subspace. Given a basis, every point in the subspace is uniquely defined, but a different basis gives different coefficients for the same point.' },
      { id: 2, dim: 2, title: 'Level 2: Bases for a Line',
        V: { gens: [[1, 2]], kind: 'line', name: 'the line y = 2x' },
        pool: [[1, 2], [2, 1], [-1, -2], [0.5, 1], [2, 4]], target: [1.5, 3], needed: 2,
        intro: 'V is the blue line y = 2x, a one-dimensional subspace of ℝ². Find a basis for V, then identify T using it. Do this with 2 different bases.',
        discuss: 'Every basis your group found for this line had exactly ONE vector. Why can\'t a basis for a line have two vectors? Why can\'t it have zero?',
        concept: 'A basis does NOT need to span the entire ambient space ℝ², just a particular subspace. Any single non-zero vector on this line is a basis for it.' },
      { id: 3, dim: 2, title: 'Level 3: Some Choices Are Traps',
        V: { gens: [[1, 0], [0, 1]], kind: 'all', name: 'all of ℝ² (the whole plane)' },
        pool: [[2, 1], [-4, -2], [1, -1], [0, 3], [1, 2]], target: [3, 3], needed: 3,
        intro: 'V is all of ℝ² again, but some of these vectors are traps. Find 3 different bases and identify T using each one.',
        discuss: 'What did every basis your group found have in common? For any choices the app rejected, which of the two basis conditions failed: spanning the entire subspace, or linear independence?',
        concept: 'Every basis for ℝ² has exactly 2 vectors: fewer cannot span all of ℝ², and more are always linearly dependent.' },
      { id: 4, dim: 3, title: 'Level 4: Bases for a Plane in ℝ³',
        V: { gens: [[2, 0, 1], [0, 2, 1]], kind: 'plane', name: 'the tilted plane z = 0.5x + 0.5y' },
        pool: [[2, 0, 1], [0, 2, 1], [2, 2, 2], [-2, 2, 0], [1, 1, 2], [4, 0, 2]], target: [2, 1, 1.5], needed: 2,
        intro: 'V is the blue tilted plane, a subspace of ℝ³. Rotate the view to see it edge-on. Find 2 different bases for V and identify T using each.',
        discuss: 'V sits inside ℝ³, but each basis only needed 2 vectors. How is the number of vectors in a basis related to the dimension of V?',
        concept: 'A basis only needs to span the subspace, not the ambient space ℝ³. V has 2 linearly independent vectors in any basis, so V has dimension 2.' },
      { id: 5, dim: 3, title: 'Level 5: Bases for All of ℝ³',
        V: { gens: [[1, 0, 0], [0, 1, 0], [0, 0, 1]], kind: 'all', name: 'all of ℝ³' },
        pool: [[2, 0, 0], [0, 2, 0], [0, 0, 2], [1, 1, 0], [1, 1, 2], [2, 2, 0]], target: [2, 4, 2], needed: 2,
        intro: 'V is all of ℝ³. Find 2 different bases and identify T using each. Watch out: some collections of three vectors are traps.',
        discuss: 'Find three vectors in the list that are NOT a basis for ℝ³, and explain to each other which condition fails. Could 4 vectors ever be a basis for ℝ³?',
        concept: 'Every basis for ℝ³ has exactly 3 linearly independent vectors.' }
    ]
  };

  const TALK = {
    predict: 'Before anyone touches the plot, go around the group: each person says their guess out loud. Then agree on ONE group answer.',
    explore: 'Before the plot controller drags, the explainer predicts where the next point will land. Were they right?',
    place:   'Everyone point at the screen: where are ALL the points you could ever build? Agree before you click Check.',
    choose:  'Before you click Check, each person says one reason this set might NOT be a basis.',
    reach:   'Estimate the λ values out loud before dragging. Who was closest?'
  };

  // ===========================================================================
  // GLOBAL STATE
  // ===========================================================================
  const group = { names: [], plans: '' };
  const notes = [];
  const progress = { span: {}, basis: {} };
  const levelState = { span: {}, basis: {} };
  let activePanel = 'span';
  const activeIdx = { span: 0, basis: 0 };
  let st = null;
  const view = { S2: 54, S3: DEFAULT_S3, lim: 4.5, yaw: DEFAULT_YAW, pitch: DEFAULT_PITCH };
  let drag = null, hover = null;

  // ===========================================================================
  // MATH HELPERS
  // ===========================================================================
  const to3 = v => [v[0], v[1], v.length > 2 ? v[2] : 0];
  const add = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
  const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
  const scl = (a, s) => [a[0] * s, a[1] * s, a[2] * s];
  const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
  const norm = a => Math.hypot(a[0], a[1], a[2]);
  const dist = (a, b) => norm(sub(a, b));
  const lerp = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];

  // Rank of a list of vectors (Gaussian elimination)
  function rank(list, tol) {
    tol = tol || 1e-6;
    const m = list.map(v => to3(v).slice());
    let r = 0;
    for (let col = 0; col < 3 && r < m.length; col++) {
      let piv = -1, best = tol;
      for (let i = r; i < m.length; i++) if (Math.abs(m[i][col]) > best) { best = Math.abs(m[i][col]); piv = i; }
      if (piv < 0) continue;
      const tmp = m[r]; m[r] = m[piv]; m[piv] = tmp;
      for (let i = 0; i < m.length; i++) {
        if (i === r) continue;
        const f = m[i][col] / m[r][col];
        for (let k = col; k < 3; k++) m[i][k] -= f * m[r][k];
      }
      r++;
    }
    return r;
  }

  function fmtNum(n) {
    const r = Math.round(n * 100) / 100;
    return Object.is(r, -0) ? '0' : r.toString();
  }
  function fmtPt(p, dim) {
    dim = dim || curDim();
    return dim === 3 ? `${fmtNum(p[0])}, ${fmtNum(p[1])}, ${fmtNum(p[2])}` : `${fmtNum(p[0])}, ${fmtNum(p[1])}`;
  }
  function comboStr(lams, names) {
    if (!lams.length) return '0';
    return lams.map((l, k) => {
      const term = `${fmtNum(Math.abs(l))}·${names[k]}`;
      if (k === 0) return (l < 0 ? '-' : '') + term;
      return (l < 0 ? ' - ' : ' + ') + term;
    }).join('');
  }
  function esc(s) {
    return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }

  // ===========================================================================
  // LEVEL STATE
  // ===========================================================================
  function curLevel() { return LEVELS[activePanel][activeIdx[activePanel]]; }
  function curDim() { return curLevel().dim; }
  function makeVec(base, color, name) { return { base: to3(base), c: 1, tail: [0, 0, 0], color: color, name: name }; }

  function getLevelState(panel, lvl) {
    const store = levelState[panel];
    if (!store[lvl.id]) {
      if (panel === 'span') {
        store[lvl.id] = {
          stage: 'predict', prediction: null,
          vecs: lvl.vecs.map((v, i) => makeVec(v, COLORS[i], VNAMES[i])),
          marked: [], shape: null, anchors: [], msg: null, result: null, answer: ''
        };
      } else {
        store[lvl.id] = {
          stage: 'predict', prediction: null, selected: [], vecs: [], found: [],
          msg: null, okMsg: null, answer: ''
        };
      }
    }
    return store[lvl.id];
  }

  function levelExtent(lvl) {
    let m = 4.5;
    const pts = [];
    if (lvl.vecs) lvl.vecs.forEach(v => pts.push(v));
    if (lvl.pool) lvl.pool.forEach(v => pts.push(v));
    if (lvl.target) pts.push(lvl.target);
    pts.forEach(p => to3(p).forEach(c => { m = Math.max(m, Math.abs(c) + 0.5); }));
    return m;
  }

  function setDefaultView() {
    const lvl = curLevel();
    view.S2 = Math.min(54, 270 / (levelExtent(lvl) + 0.6));
    view.S3 = DEFAULT_S3;
    view.yaw = DEFAULT_YAW;
    view.pitch = DEFAULT_PITCH;
    syncLim();
  }
  function syncLim() {
    view.lim = Math.max(levelExtent(curLevel()), 280 / view.S2 - 0.4);
  }

  function loadLevel(panel, idx) {
    activePanel = panel;
    activeIdx[panel] = idx;
    st = getLevelState(panel, curLevel());
    drag = null; hover = null;
    setDefaultView();
    renderLevelBar();
    renderSide();
    draw();
  }

  // Which vectors can be dragged right now
  function vecsInteractive() {
    return (activePanel === 'span' && (st.stage === 'explore' || st.stage === 'more')) || (activePanel === 'basis' && st.stage === 'reach');
  }
  // Panel 1: free building (before placing the span, or the bonus round after the level)
  function spanBuilding() { return activePanel === 'span' && (st.stage === 'explore' || st.stage === 'more'); }

  // ===========================================================================
  // CHAINS (tip-to-tail paths starting at the origin)
  // ===========================================================================
  function tipOf(v) { return add(v.tail, scl(v.base, v.c)); }
  function isActive(v) { return Math.abs(v.c) >= 0.08; }

  function chainPaths() {
    const n = st.vecs.length, out = [];
    (function dfs(cur, used, path) {
      if (path.length) out.push({ tip: cur, path: path.slice() });
      for (let i = 0; i < n; i++) {
        if (used & (1 << i)) continue;
        const v = st.vecs[i];
        if (!isActive(v)) continue;
        if (dist(v.tail, cur) <= 0.28) dfs(tipOf(v), used | (1 << i), path.concat([i]));
      }
    })([0, 0, 0], 0, []);
    return out;
  }

  // The end of the longest chain from the origin (the point the group is currently "building")
  function currentEnd() {
    const act = st.vecs.filter(isActive);
    if (!act.length) return { tip: [0, 0, 0], path: [] };
    const ps = chainPaths();
    if (!ps.length) return null;
    ps.sort((a, b) => b.path.length - a.path.length);
    return ps[0];
  }

  // ===========================================================================
  // PANEL 1: SPAN LOGIC
  // ===========================================================================
  function shapeOptions(dim) {
    return dim === 2
      ? [['origin', 'Just the origin (a single point)'], ['line', 'A line through the origin'], ['all', 'The whole plane']]
      : [['origin', 'Just the origin (a single point)'], ['line', 'A line through the origin'], ['plane', 'A plane through the origin'], ['all', 'All of 3D space']];
  }
  function shapeDim(shape, n) { return { origin: 0, line: 1, plane: 2, all: n }[shape]; }
  function shapeWord(shape, n) {
    return { origin: 'single point', line: 'line', plane: 'plane', all: n === 2 ? 'whole plane' : 'all of 3D space' }[shape];
  }
  function anchorsNeeded(shape) { return shape === 'line' ? 1 : shape === 'plane' ? 2 : 0; }

  function markPoint() {
    const end = currentEnd();
    if (!end) return;
    const p = end.tip.map(x => Math.round(x * 100) / 100);
    if (st.marked.some(m => dist(m.p, p) < 0.1)) {
      st.msg = 'You already marked that point. Try building a different one!';
    } else {
      const lams = end.path.map(i => st.vecs[i].c);
      const names = end.path.map(i => st.vecs[i].name);
      st.marked.push({ p: p, combo: comboStr(lams, names) });
      st.msg = null;
    }
    renderSide(); draw();
  }

  function checkSpan() {
    const lvl = curLevel(), n = lvl.dim, d = rank(lvl.vecs);
    if (!st.shape) return { ok: false, msg: 'Pick a shape first.' };
    const need = anchorsNeeded(st.shape);
    const anchors = st.anchors.map(k => st.marked[k].p);
    const word = shapeWord(st.shape, n);
    if (anchors.length < need) {
      return { ok: false, msg: `Click ${need - anchors.length} more of your marked points on the plot to pin down your ${word}.` };
    }
    if (need > 0 && rank(anchors, 1e-4) < need) {
      return { ok: false, msg: st.shape === 'line'
        ? 'That point is the origin. A line through the origin needs a second point that is not the origin.'
        : 'Those two points lie on the same line through the origin, so they do not pin down a plane. Pick two points that point in different directions. (If you cannot find two like that, what does that tell you?)' };
    }
    const sd = shapeDim(st.shape, n);
    if (sd < d) {
      const r0 = rank(anchors, 1e-4);
      const off = st.marked.find(m => rank(anchors.concat([m.p]), 1e-4) > r0);
      if (off) {
        return { ok: false, msg: `Look at the point (${fmtPt(off.p)}) that you built as ${off.combo}. It is NOT on your ${word}, so the span must be bigger than that.` };
      }
      return { ok: false, msg: `Every point you marked fits on your ${word}... but is that everything you could build? Go back, try different λ values or different chains, and see if you can build a point that is NOT on it.` };
    }
    if (sd > d) {
      if (d === 1) return { ok: false, msg: 'Can you actually build a point that is OFF a single line through the origin? Look at your marked points: do they all line up? Go back and try. If every point lands on one line, that line is the span.' };
      if (d === 2) return { ok: false, msg: 'Can you build a point anywhere in 3D? Rotate the view: do your points all sit on one flat sheet? Try to build a point above or below that sheet. If you cannot, the span is smaller than all of 3D.' };
      return { ok: false, msg: 'You can only build the origin? Try stretching the vectors.' };
    }
    return { ok: true };
  }

  function spanResultHTML() {
    const lvl = curLevel(), n = lvl.dim, d = rank(lvl.vecs);
    const names = lvl.vecs.map((v, i) => VNAMES[i]).join(', ');
    const shape = d === 0 ? 'origin' : d === 1 ? 'line' : (d === 2 && n === 3) ? 'plane' : 'all';
    let h = `<strong>Correct!</strong> span({${names}}) is ${shape === 'all' ? (n === 2 ? 'all of ℝ², the whole plane' : 'all of ℝ³') : 'a ' + shapeWord(shape, n) + ' through the origin'}. `;
    h += `All ${st.marked.length} points you built are in it.`;
    if (st.prediction) {
      const p = shapeOptions(n).find(o => o[0] === st.prediction);
      h += (st.prediction === shape)
        ? `<br>Your group predicted <em>“${p[1]}”</em> before playing. Nice call!`
        : `<br>Your group predicted <em>“${p[1]}”</em> before playing. What changed your minds?`;
    }
    h += `<br><span style="display:block;margin-top:6px;">${lvl.concept}</span>`;
    return h;
  }

  // ===========================================================================
  // PANEL 2: BASIS LOGIC
  // ===========================================================================
  function vShapeWord(lvl) { return lvl.V.name; }

  function checkBasis() {
    const lvl = curLevel(), dV = rank(lvl.V.gens);
    const S = st.selected.map(i => lvl.pool[i]);
    if (!S.length) return { ok: false, msg: 'Click vectors in the list to add them to your basis.' };
    const outside = st.selected.filter(i => rank(lvl.V.gens.concat([lvl.pool[i]])) > dV);
    if (outside.length) {
      const i = outside[0];
      return { ok: false, msg: `${PNAMES[i]} = (${fmtPt(to3(lvl.pool[i]))}) is not in V: it points out of ${vShapeWord(lvl)}. Every vector in a basis for V has to live in V.` };
    }
    const r = rank(S);
    if (r < S.length) {
      const red = st.selected.find(i => rank(st.selected.filter(j => j !== i).map(j => lvl.pool[j])) === r);
      const others = st.selected.filter(j => j !== red).map(j => PNAMES[j]).join(', ');
      return { ok: false, msg: `Condition 2 fails: these vectors are linearly dependent. ${PNAMES[red]} can be expressed as a linear combination of ${others}, so it adds nothing new. Try removing one.` };
    }
    if (r < dV) {
      return { ok: false, msg: `Condition 1 fails: these vectors are linearly independent, but they only span a ${['single point', 'line', 'plane'][r]}. V is ${vShapeWord(lvl)}, so they do not span that entire subspace. Add a vector.` };
    }
    const key = st.selected.slice().sort().join(',');
    if (st.found.some(f => f.key === key)) return { ok: false, msg: 'Your group already used this exact basis! Find a different one.' };
    return { ok: true, key: key };
  }

  function startReach(key) {
    const lvl = curLevel();
    st.reachKey = key;
    st.reachIds = st.selected.slice();   // keep the order the group picked: order matters for the coefficients
    st.vecs = st.reachIds.map(i => makeVec(lvl.pool[i], COLORS[i], PNAMES[i]));
    st.stage = 'reach';
    st.msg = null;
    st.okMsg = `{${st.reachIds.map(i => PNAMES[i]).join(', ')}} is a basis for V: (1) the vectors span that entire subspace, and (2) they are linearly independent.`;
  }

  function reachHit() {
    const t = to3(curLevel().target);
    const actN = st.vecs.filter(isActive).length;
    return chainPaths().find(p => p.path.length === actN && actN > 0 && dist(p.tip, t) <= 0.28) || null;
  }

  function recordCoords() {
    if (!reachHit()) return;
    const lvl = curLevel();
    const coords = st.vecs.map(v => isActive(v) ? Math.round(v.c * 100) / 100 : 0);
    st.found.push({ key: st.reachKey, ids: st.reachIds.slice(), coords: coords });
    st.vecs = [];
    st.selected = [];
    if (st.extra) {
      // bonus round after the level: keep checking bases until the group clicks Done
      st.stage = 'choose';
      st.msg = null;
      st.okMsg = `Recorded! That makes ${st.found.length} bases for the same V. Try another one, or click "Done checking bases".`;
    } else if (st.found.length >= lvl.needed) {
      st.stage = 'discuss';
      st.msg = null;
    } else {
      st.stage = 'choose';
      st.msg = null;
      st.okMsg = `Recorded! Now find a DIFFERENT basis for the same V (${st.found.length} of ${lvl.needed} found).`;
    }
  }

  function coordTableHTML() {
    const lvl = curLevel();
    if (!st.found.length) return '';
    let h = `<table class="coord-table"><tr><th>Basis</th><th>Linear combination</th><th>T using this basis</th></tr>`;
    st.found.forEach(f => {
      const names = f.ids.map(i => PNAMES[i]);
      h += `<tr><td>{${names.join(', ')}}</td><td>${comboStr(f.coords, names)}</td><td>(${f.coords.map(fmtNum).join(', ')})</td></tr>`;
    });
    h += `</table><div style="font-size:0.78rem;color:#475569;margin-top:4px;">Same point T = (${fmtPt(to3(lvl.target))}) every time.</div>`;
    return h;
  }

  function basisResultHTML() {
    const lvl = curLevel(), dV = rank(lvl.V.gens);
    let h = `<strong>Level cleared!</strong> Your group found ${st.found.length} different bases for V, and every one had exactly ${dV} vector${dV === 1 ? '' : 's'}.`;
    if (st.prediction) {
      h += (Number(st.prediction) === dV)
        ? `<br>You predicted a basis would need ${st.prediction}. Correct!`
        : `<br>You predicted a basis would need ${st.prediction}. It actually needs ${dV}. Why?`;
    }
    h += `<br><span style="display:block;margin-top:6px;">${lvl.concept}</span>`;
    return h;
  }

  // ===========================================================================
  // ROLES & NOTES
  // ===========================================================================
  function roleHTML() {
    const n = group.names.length;
    if (n < 2) return '';
    const k = (activePanel === 'span' ? 0 : LEVELS.span.length) + activeIdx[activePanel];
    const driver = group.names[k % n], explainer = group.names[(k + 1) % n];
    return `<div class="role-line"><strong>Roles this level:</strong><br>${esc(explainer)}: explain the group's thinking out loud.<br>${esc(driver)}: control the plot. Everyone else, tell ${esc(driver)} what to try next.</div>`;
  }

  function saveAnswer(text) {
    const lvl = curLevel();
    st.answer = text;
    let pred = '';
    if (st.prediction) {
      pred = activePanel === 'span'
        ? (shapeOptions(lvl.dim).find(o => o[0] === st.prediction) || ['', ''])[1]
        : st.prediction + ' vector(s)';
    }
    notes.push({
      panel: activePanel === 'span' ? 'Span' : 'Bases',
      level: lvl.title, prediction: pred,
      question: lvl.discuss, answer: text,
      time: new Date().toLocaleTimeString()
    });
    progress[activePanel][lvl.id] = true;
    st.stage = 'done';
    pushNotes();
  }

  function pushNotes() {
    if (window.Shiny && Shiny.setInputValue) {
      Shiny.setInputValue('notes_json', JSON.stringify({ names: group.names, plans: group.plans, notes: notes }), { priority: 'event' });
    }
    renderNotes();
  }

  function renderNotes() {
    const el = document.getElementById('notesView');
    if (!el) return;
    let h = `<div class="notes-card"><h5>Our group</h5><p><strong>Members:</strong> ${esc(group.names.join(', ') || '(not entered yet)')}</p>`;
    h += `<p><strong>This weekend / looking forward to:</strong><br>${esc(group.plans || '(not entered yet)').replace(/\n/g, '<br>')}</p></div>`;
    h += `<div class="notes-card"><h5>Our discussion answers (${notes.length})</h5>`;
    if (!notes.length) {
      h += `<p class="text-muted">Answers you save at the end of each level show up here.</p>`;
    } else {
      h += `<table class="notes-table"><tr><th>Panel</th><th>Level</th><th>Prediction</th><th>Question</th><th>Our answer</th></tr>`;
      notes.forEach(n => {
        h += `<tr><td>${esc(n.panel)}</td><td>${esc(n.level)}</td><td>${esc(n.prediction)}</td><td>${esc(n.question)}</td><td>${esc(n.answer)}</td></tr>`;
      });
      h += `</table>`;
    }
    h += `</div>`;
    el.innerHTML = h;
  }

  // ===========================================================================
  // UI: LEVEL BAR & SIDE PANEL
  // ===========================================================================
  const workspaceHTML = `
    <div class="level-bar" id="levelBar"></div>
    <div class="workspace-grid">
      <div class="control-card" id="sideCard"></div>
      <div class="canvas-card">
        <div class="zoom-bar">
          <button id="btnZoomIn" class="zoom-btn" title="Zoom in">+</button>
          <button id="btnZoomOut" class="zoom-btn" title="Zoom out">&minus;</button>
          <button id="btnZoomReset" class="zoom-btn zoom-reset" title="Reset zoom and rotation">Reset view</button>
        </div>
        <div class="canvas-wrap" id="canvasWrap"><canvas id="labCanvas" width="860" height="560"></canvas></div>
        <div id="helpStrip" class="help-strip"></div>
      </div>
    </div>`;

  function renderLevelBar() {
    const bar = document.getElementById('levelBar');
    if (!bar) return;
    bar.innerHTML = '';
    LEVELS[activePanel].forEach((lvl, i) => {
      const b = document.createElement('button');
      const done = !!progress[activePanel][lvl.id];
      b.className = 'lvl-btn' + (i === activeIdx[activePanel] ? ' active' : '') + (done ? ' done' : '');
      b.innerHTML = `<span>L${lvl.id}${done ? ' ✓' : ''}</span><span class="dim-tag">${lvl.dim}D</span>`;
      b.onclick = () => loadLevel(activePanel, i);
      bar.appendChild(b);
    });
  }

  const STAGE_LABEL = {
    span:  { predict: 'Step 1 of 4: Group prediction', explore: 'Step 2 of 4: Build points', place: 'Step 3 of 4: Place the span', discuss: 'Step 4 of 4: Group discussion', done: 'Level complete', more: 'Bonus: span more points' },
    basis: { predict: 'Step 1: Group prediction', choose: 'Step 2: Pick a basis', reach: 'Step 3: Identify T using your basis', discuss: 'Step 4: Group discussion', done: 'Level complete' }
  };
  function stageLabel() {
    if (activePanel === 'basis' && st.extra && (st.stage === 'choose' || st.stage === 'reach')) return 'Bonus: check more bases';
    return STAGE_LABEL[activePanel][st.stage];
  }

  // "keep exploring" buttons shown once a level is solved
  function moreButtonHTML() {
    return activePanel === 'span'
      ? `<button id="btnMore" class="btn-lab btn-alt">Span more points on the subspace</button>`
      : `<button id="btnMore" class="btn-lab btn-alt">Check more bases</button>`;
  }

  function talkBox(stage) {
    return TALK[stage] ? `<div class="talk-box"><div class="talk-head">Talk it out</div>${TALK[stage]}</div>` : '';
  }

  function discussHTML() {
    const lvl = curLevel();
    return `<div class="discuss-card"><div class="talk-head">Group discussion: talk first, then type</div>
      ${esc(lvl.discuss)}
      <textarea id="discussText" placeholder="Write your group's answer in 1-3 sentences. The explainer reads it out loud.">${esc(st.answer || '')}</textarea>
      <div id="discussCount" style="font-size:0.75rem;color:#475569;margin-top:2px;"></div>
      <button id="btnSaveAnswer" class="btn-lab btn-go" disabled>Save our answer &amp; finish the level</button></div>`;
  }

  function nextButtonHTML() {
    const more = activeIdx[activePanel] < LEVELS[activePanel].length - 1;
    return more ? `<button id="btnNextLevel" class="btn-lab btn-next">Next level &rarr;</button>`
                : `<div class="result-box">That was the last level on this panel. ${activePanel === 'span' ? 'Head to the Bases panel next!' : 'Check the Group Notes tab to see everything your group wrote.'}</div>`;
  }

  function renderSide() {
    const card = document.getElementById('sideCard');
    if (!card) return;
    const lvl = curLevel();
    let h = roleHTML();
    h += `<span class="stage-badge">${stageLabel()}</span>`;
    h += `<h5 class="lvl-title">${lvl.title}</h5>`;
    h += activePanel === 'span'
      ? `<div class="def-chip"><strong>Span:</strong> span({v1, &hellip;, vn}) = {λ1·v1 + &hellip; + λn·vn : λ ∈ ℝ}, the set of all points that can be reached by stretching and combining the vectors.</div>`
      : `<div class="def-chip"><strong>Basis:</strong> a collection of vectors is a basis for a subspace V if (1) it spans that entire subspace and (2) it is linearly independent. It is the coordinate system for V.</div>`;
    h += `<p class="lvl-intro">${lvl.intro}</p>`;

    if (activePanel === 'span') {
      if (st.stage === 'predict') {
        h += talkBox('predict');
        h += `<strong style="font-size:0.88rem;">What shape will the span of these vectors be?</strong><div class="choice-grid">`;
        shapeOptions(lvl.dim).forEach(o => { h += `<button class="choice${st.prediction === o[0] ? ' sel' : ''}" data-pred="${o[0]}">${o[1]}</button>`; });
        h += `</div><button id="btnLockPred" class="btn-lab btn-alt" ${st.prediction ? '' : 'disabled'}>Lock in our prediction &amp; start</button>`;
      } else if (st.stage === 'explore') {
        h += `<div id="statusPill" class="status-pill pill-neutral"></div>`;
        h += `<button id="btnMark" class="btn-lab btn-go">Mark this point</button>`;
        h += `<button id="btnResetVecs" class="btn-lab btn-soft">Reset vectors</button>`;
        h += `<button id="btnToPlace" class="btn-lab btn-alt" ${st.marked.length >= 3 ? '' : 'disabled'}>We have enough points: place the span &rarr;</button>`;
        if (st.msg) h += `<div class="msg-box">${st.msg}</div>`;
        h += talkBox('explore');
        h += `<div id="readout" class="readout"></div>`;
      } else if (st.stage === 'place') {
        h += `<strong style="font-size:0.88rem;">Where are ALL the points you could build? Choose a shape:</strong><div class="choice-grid">`;
        shapeOptions(lvl.dim).forEach(o => { h += `<button class="choice${st.shape === o[0] ? ' sel' : ''}" data-shape="${o[0]}">${o[1]}</button>`; });
        h += `</div>`;
        const need = anchorsNeeded(st.shape);
        if (need) h += `<div class="talk-box" style="background:#f5f3ff;border-color:#c4b5fd;color:#4c1d95;">Now click ${need === 1 ? 'one of your marked points' : 'two of your marked points'} on the plot to pin your ${st.shape} in place (${st.anchors.length} of ${need} chosen). It will appear in purple.</div>`;
        h += `<button id="btnCheckSpan" class="btn-lab btn-go" ${st.shape ? '' : 'disabled'}>Check our span</button>`;
        h += `<button id="btnBackExplore" class="btn-lab btn-soft">&larr; Back to building points</button>`;
        if (st.msg) h += `<div class="msg-box">${st.msg}</div>`;
        h += talkBox('place');
        h += `<div id="readout" class="readout"></div>`;
      } else if (st.stage === 'more') {
        h += `<div class="result-box"><strong>Bonus round.</strong> The span is shown in green. Keep stretching and combining the vectors and mark more points. Where does every new point land?</div>`;
        h += `<div id="statusPill" class="status-pill pill-neutral"></div>`;
        h += `<button id="btnMark" class="btn-lab btn-go">Mark this point</button>`;
        h += `<button id="btnResetVecs" class="btn-lab btn-soft">Reset vectors</button>`;
        h += `<button id="btnMoreDone" class="btn-lab btn-next">Done exploring &rarr;</button>`;
        if (st.msg) h += `<div class="msg-box">${st.msg}</div>`;
        h += `<div id="readout" class="readout"></div>`;
      } else {
        h += `<div class="result-box">${spanResultHTML()}</div>`;
        h += moreButtonHTML();
        if (st.stage === 'discuss') h += discussHTML();
        else h += `<div style="font-size:0.84rem;"><strong>Your group's answer:</strong><div class="saved-answer">${esc(st.answer)}</div></div>` + nextButtonHTML();
      }
    } else {
      const dV = rank(lvl.V.gens);
      if (st.stage === 'predict') {
        h += talkBox('predict');
        h += `<strong style="font-size:0.88rem;">V is ${lvl.V.name}. How many vectors do you think a basis for V needs?</strong><div class="choice-grid">`;
        for (let k = 1; k <= lvl.dim; k++) h += `<button class="choice${st.prediction === String(k) ? ' sel' : ''}" data-pred="${k}">${k} vector${k === 1 ? '' : 's'}</button>`;
        h += `</div><button id="btnLockPred" class="btn-lab btn-alt" ${st.prediction ? '' : 'disabled'}>Lock in our prediction &amp; start</button>`;
      } else if (st.stage === 'choose') {
        if (st.okMsg) h += `<div class="result-box">${st.okMsg}</div>`;
        h += st.extra
          ? `<strong style="font-size:0.88rem;">Bonus round: click vectors to put them in a basis, in order (${st.found.length} bases found so far):</strong>`
          : `<strong style="font-size:0.88rem;">Click vectors to put them in your basis, in order (${st.found.length} of ${lvl.needed} bases found):</strong>`;
        lvl.pool.forEach((p, i) => {
          const sel = st.selected.includes(i);
          h += `<button class="pool-chip${sel ? ' sel' : ''}" data-pool="${i}" style="border-color:${COLORS[i]};color:${COLORS[i]};">
                  <span>${PNAMES[i]} = (${fmtPt(to3(p))})</span><span class="chk">${sel ? ['1st', '2nd', '3rd', '4th', '5th', '6th'][st.selected.indexOf(i)] + ' in basis ✓' : 'click to add'}</span></button>`;
        });
        h += `<button id="btnCheckBasis" class="btn-lab btn-go" ${st.selected.length ? '' : 'disabled'}>Check our basis</button>`;
        if (st.extra) h += `<button id="btnMoreDone" class="btn-lab btn-next">Done checking bases &rarr;</button>`;
        if (st.msg) h += `<div class="msg-box">${st.msg}</div>`;
        h += talkBox('choose');
        h += coordTableHTML();
      } else if (st.stage === 'reach') {
        h += `<div class="result-box">${st.okMsg}</div>`;
        h += `<div id="statusPill" class="status-pill pill-neutral"></div>`;
        h += `<button id="btnRecord" class="btn-lab btn-go" disabled>Record T using this basis</button>`;
        h += `<button id="btnBackChoose" class="btn-lab btn-soft">&larr; Pick different vectors</button>`;
        h += talkBox('reach');
        h += `<div id="readout" class="readout"></div>`;
        h += coordTableHTML();
      } else {
        h += `<div class="result-box">${basisResultHTML()}</div>` + coordTableHTML();
        h += moreButtonHTML();
        if (st.stage === 'discuss') h += discussHTML();
        else h += `<div style="font-size:0.84rem;margin-top:8px;"><strong>Your group's answer:</strong><div class="saved-answer">${esc(st.answer)}</div></div>` + nextButtonHTML();
      }
    }
    card.innerHTML = h;
    bindSide();
    updateLive();
    renderHelp();
  }

  function bindSide() {
    const card = document.getElementById('sideCard');
    const lvl = curLevel();
    card.querySelectorAll('[data-pred]').forEach(b => b.onclick = () => { st.prediction = b.getAttribute('data-pred'); renderSide(); });
    const on = (id, fn) => { const el = document.getElementById(id); if (el) el.onclick = fn; };
    on('btnLockPred', () => {
      st.stage = activePanel === 'span' ? 'explore' : 'choose';
      renderSide(); draw();
    });
    // span panel
    on('btnMark', markPoint);
    on('btnResetVecs', () => { st.vecs = lvl.vecs.map((v, i) => makeVec(v, COLORS[i], VNAMES[i])); st.msg = null; renderSide(); draw(); });
    on('btnToPlace', () => { st.stage = 'place'; st.msg = null; renderSide(); draw(); });
    on('btnBackExplore', () => { st.stage = 'explore'; st.msg = null; renderSide(); draw(); });
    card.querySelectorAll('[data-shape]').forEach(b => b.onclick = () => {
      st.shape = b.getAttribute('data-shape');
      st.anchors = st.anchors.slice(0, anchorsNeeded(st.shape));
      st.msg = null; renderSide(); draw();
    });
    on('btnCheckSpan', () => {
      const r = checkSpan();
      if (r.ok) { st.stage = 'discuss'; st.msg = null; }
      else st.msg = r.msg;
      renderSide(); draw();
    });
    // basis panel
    card.querySelectorAll('[data-pool]').forEach(b => b.onclick = () => {
      const i = Number(b.getAttribute('data-pool'));
      st.selected = st.selected.includes(i) ? st.selected.filter(j => j !== i) : st.selected.concat([i]);
      st.msg = null; st.okMsg = null; renderSide(); draw();
    });
    on('btnCheckBasis', () => {
      const r = checkBasis();
      if (r.ok) startReach(r.key); else st.msg = r.msg;
      renderSide(); draw();
    });
    on('btnRecord', () => { recordCoords(); renderSide(); draw(); });
    on('btnBackChoose', () => { st.stage = 'choose'; st.vecs = []; st.okMsg = null; renderSide(); draw(); });
    // discussion
    const ta = document.getElementById('discussText');
    if (ta) {
      const upd = () => {
        const len = ta.value.trim().length;
        document.getElementById('btnSaveAnswer').disabled = len < 25;
        document.getElementById('discussCount').textContent = len < 25 ? `Keep going: write at least a full sentence (${len}/25 characters).` : 'Looks good. Make sure everyone agrees before saving!';
      };
      ta.oninput = upd; upd();
      on('btnSaveAnswer', () => { saveAnswer(ta.value.trim()); renderLevelBar(); renderSide(); draw(); });
    }
    on('btnNextLevel', () => loadLevel(activePanel, activeIdx[activePanel] + 1));
    // bonus rounds after a level is solved
    on('btnMore', () => {
      st.returnStage = st.stage;            // 'discuss' (answer not saved yet) or 'done'
      if (activePanel === 'span') {
        st.stage = 'more';
      } else {
        st.extra = true; st.stage = 'choose'; st.selected = []; st.vecs = [];
        st.okMsg = 'Bonus round: try any other basis for the same V. Each one you record is added to the table.';
      }
      st.msg = null; renderSide(); draw();
    });
    on('btnMoreDone', () => {
      st.stage = st.returnStage || 'done';
      st.extra = false; st.selected = []; if (activePanel === 'basis') st.vecs = [];
      st.msg = null; st.okMsg = null; renderSide(); draw();
    });
  }

  // Cheap updates while dragging (no rebuild of the side panel)
  function updateLive() {
    const pill = document.getElementById('statusPill');
    const ro = document.getElementById('readout');
    const lvl = curLevel();
    if (activePanel === 'span' && (st.stage === 'explore' || st.stage === 'place' || st.stage === 'more')) {
      const end = currentEnd();
      if (pill) {
        if (!end) { pill.className = 'status-pill pill-warning'; pill.textContent = 'Your vectors are not chained to the origin. Drag a shaft so its tail snaps onto the origin or onto another vector\'s tip.'; }
        else { pill.className = 'status-pill pill-neutral'; pill.textContent = `Current point: (${fmtPt(end.tip)}) = ${comboStr(end.path.map(i => st.vecs[i].c), end.path.map(i => st.vecs[i].name))}`; }
      }
      const mb = document.getElementById('btnMark');
      if (mb) mb.disabled = !end;
      if (ro) {
        let h = '';
        st.vecs.forEach(v => { h += `<div class="row-r"><span style="color:${v.color};font-weight:700;">λ = ${fmtNum(v.c)} &middot; ${v.name} = (${fmtPt(v.base)})</span></div>`; });
        h += `<div class="row-r"><strong>Points you built (${st.marked.length}):</strong></div>`;
        st.marked.forEach((m, k) => {
          const isA = st.anchors.includes(k);
          h += `<div class="row-r"><span ${isA ? 'style="color:#7c3aed;font-weight:700;"' : ''}>P${k + 1} = (${fmtPt(m.p)})</span><span class="text-muted">${m.combo}</span></div>`;
        });
        ro.innerHTML = h;
      }
    }
    if (activePanel === 'basis' && st.stage === 'reach') {
      const hit = reachHit();
      if (pill) {
        pill.className = 'status-pill ' + (hit ? 'pill-success' : 'pill-neutral');
        pill.textContent = hit ? 'You reached T! Click "Record" to save the coefficients that identify T using this basis.' : `Find the coefficients: stretch and chain your basis vectors from the origin to T(${fmtPt(to3(lvl.target))}).`;
      }
      const rb = document.getElementById('btnRecord');
      if (rb) rb.disabled = !hit;
      if (ro) {
        let h = '';
        st.vecs.forEach(v => { h += `<div class="row-r"><span style="color:${v.color};font-weight:700;">λ = ${fmtNum(v.c)} &middot; ${v.name} = (${fmtPt(v.base)})</span><span class="text-muted">tip (${fmtPt(tipOf(v))})</span></div>`; });
        ro.innerHTML = h;
      }
    }
  }

  function renderHelp() {
    const el = document.getElementById('helpStrip');
    if (!el) return;
    const d3 = curDim() === 3;
    let h = '';
    if (vecsInteractive()) {
      h = d3
        ? '<strong>3D controls:</strong> Drag an <strong>arrowhead</strong> to stretch a vector by λ. Drag its hollow <strong>floor circle</strong> to move it in the x and y directions. Drag its <strong>shaft</strong> up or down to move it in the z direction. Tails snap onto the origin and onto other tips. '
        : '<strong>Controls:</strong> Drag an <strong>arrowhead</strong> to stretch a vector by λ (past the tail makes λ negative). Drag a <strong>shaft</strong> to move it; its tail snaps onto the origin and onto other tips. ';
    } else if (activePanel === 'span' && st.stage === 'place') {
      h = 'Pick a shape on the left, then <strong>click your marked points</strong> on the plot to pin it in place. ';
    } else {
      h = 'Follow the steps on the left. ';
    }
    h += d3 ? '<strong>Drag empty space to rotate</strong>; scroll or use + / &minus; to zoom.' : 'Scroll or use + / &minus; to zoom.';
    el.innerHTML = h;
  }

  // ===========================================================================
  // PROJECTION
  // ===========================================================================
  function project(p, W, H) {
    const cx = W / 2, cy = H / 2;
    if (curDim() === 2) return [cx + p[0] * view.S2, cy - p[1] * view.S2];
    const cY = Math.cos(view.yaw), sY = Math.sin(view.yaw), sP = Math.sin(view.pitch), cP = Math.cos(view.pitch);
    const f = p[0] * sY + p[1] * cY;
    return [cx + (p[0] * cY - p[1] * sY) * view.S3, cy - (f * sP + p[2] * cP) * view.S3];
  }
  function toViewer() {
    return [-Math.sin(view.yaw) * Math.cos(view.pitch), -Math.cos(view.yaw) * Math.cos(view.pitch), Math.sin(view.pitch)];
  }
  function unproject2D(sx, sy, W, H) { return [(sx - W / 2) / view.S2, (H / 2 - sy) / view.S2, 0]; }
  function unprojectFloor(sx, sy, fixedZ, W, H) {
    const sP = Math.sin(view.pitch), cP = Math.cos(view.pitch);
    const sPs = Math.abs(sP) < 0.06 ? (sP < 0 ? -0.06 : 0.06) : sP;
    const u = (sx - W / 2) / view.S3;
    const v = -((sy - H / 2) / view.S3 + fixedZ * cP) / sPs;
    const cY = Math.cos(view.yaw), sY = Math.sin(view.yaw);
    return [u * cY + v * sY, -u * sY + v * cY];
  }

  // ===========================================================================
  // DRAWING HELPERS (screen space)
  // ===========================================================================
  function strokeLine(ctx, a, b, s) {
    ctx.save();
    ctx.strokeStyle = s.color; ctx.lineWidth = s.width || 1; ctx.lineCap = s.cap || 'round';
    ctx.globalAlpha = s.alpha == null ? 1 : s.alpha;
    if (s.dash) ctx.setLineDash(s.dash);
    ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.stroke();
    ctx.restore();
  }
  function arrowHead(ctx, from, to, color, size, alpha) {
    const ang = Math.atan2(to[1] - from[1], to[0] - from[0]);
    if (Math.hypot(to[0] - from[0], to[1] - from[1]) < 2) return;
    ctx.save();
    ctx.fillStyle = color; ctx.globalAlpha = alpha == null ? 1 : alpha;
    ctx.beginPath();
    ctx.moveTo(to[0], to[1]);
    ctx.lineTo(to[0] - size * Math.cos(ang - 0.38), to[1] - size * Math.sin(ang - 0.38));
    ctx.lineTo(to[0] - size * Math.cos(ang + 0.38), to[1] - size * Math.sin(ang + 0.38));
    ctx.closePath(); ctx.fill();
    ctx.restore();
  }
  function circle(ctx, s, r, fill, stroke, lw, alpha, dash) {
    ctx.save();
    ctx.globalAlpha = alpha == null ? 1 : alpha;
    if (dash) ctx.setLineDash(dash);
    ctx.beginPath(); ctx.arc(s[0], s[1], r, 0, Math.PI * 2);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
    ctx.restore();
  }
  function text(ctx, str, s, color, font, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha == null ? 1 : alpha;
    ctx.fillStyle = color; ctx.font = font || 'bold 12px Inter, sans-serif';
    ctx.fillText(str, s[0], s[1]);
    ctx.restore();
  }
  function fillPoly(ctx, pts, color, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha; ctx.fillStyle = color;
    ctx.beginPath(); pts.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]));
    ctx.closePath(); ctx.fill();
    ctx.restore();
  }

  // Unit vectors spanning a plane through the origin (Gram-Schmidt)
  function planeBasis(u, w) {
    const e1 = scl(u, 1 / norm(u));
    const w2 = sub(w, scl(e1, dot(w, e1)));
    return [e1, scl(w2, 1 / norm(w2))];
  }
  // Clip a line through the origin with direction u to the box
  function lineInBox(u, lim) {
    let t = Infinity;
    u.forEach(c => { if (Math.abs(c) > 1e-9) t = Math.min(t, lim / Math.abs(c)); });
    return [scl(u, -t), scl(u, t)];
  }

  // ===========================================================================
  // RENDER
  // ===========================================================================
  // Match the canvas drawing size to its on-screen size. Measure the WRAPPER, never the
  // canvas itself: measuring the canvas created a feedback loop where each redraw nudged
  // the layout narrower (panels crept toward the center while rotating).
  function fitCanvas() {
    const c = document.getElementById('labCanvas');
    const wrap = document.getElementById('canvasWrap');
    if (!c || !wrap) return;
    const w = Math.floor(wrap.clientWidth) - 2;   // minus the canvas's 1px left/right border
    if (w > 200 && w !== c.width) c.width = w;
  }

  // What should be drawn as "the student's span" and "V"
  function overlays() {
    const lvl = curLevel(), out = [];
    if (activePanel === 'span' && (st.stage === 'place' || st.stage === 'discuss' || st.stage === 'done' || st.stage === 'more') && st.shape) {
      const ok = st.stage !== 'place';
      const anchors = st.anchors.map(k => st.marked[k].p);
      const col = ok ? OK_COLOR : SPAN_COLOR;
      if (st.shape === 'origin') out.push({ kind: 'origin', color: col });
      else if (st.shape === 'all') out.push({ kind: 'all', color: col, label: ok ? (lvl.dim === 3 ? 'Span = all of ℝ³ (the whole box)' : 'Span = all of ℝ²') : (lvl.dim === 3 ? 'Your span: all of ℝ³' : 'Your span: all of ℝ²') });
      else if (st.shape === 'line' && anchors.length >= 1 && norm(anchors[0]) > 1e-6) out.push({ kind: 'line', dir: anchors[0], color: col });
      else if (st.shape === 'plane' && anchors.length >= 2 && rank(anchors, 1e-4) === 2) out.push({ kind: 'plane', u: anchors[0], w: anchors[1], color: col });
    }
    if (activePanel === 'basis') {
      const g = lvl.V.gens.map(to3);
      if (lvl.V.kind === 'line') out.push({ kind: 'line', dir: g[0], color: V_COLOR, label: 'V' });
      else if (lvl.V.kind === 'plane') out.push({ kind: 'plane', u: g[0], w: g[1], color: V_COLOR, label: 'V' });
      else out.push({ kind: 'all', color: V_COLOR, label: lvl.dim === 2 ? 'V = all of ℝ²' : 'V = all of ℝ³ (the whole box)' });
    }
    return out;
  }

  // Faint, non-interactive vectors from the pool (basis panel, choosing)
  function poolGhosts() {
    if (activePanel !== 'basis' || st.stage !== 'choose') return [];
    const lvl = curLevel();
    return lvl.pool.map((p, i) => ({ p: to3(p), color: COLORS[i], name: PNAMES[i], sel: st.selected.includes(i) }));
  }

  function markedPoints() {
    if (activePanel !== 'span' || st.stage === 'predict') return [];
    return st.marked.map((m, k) => ({ p: m.p, k: k, anchor: st.anchors.includes(k) }));
  }

  function draw() {
    const c = document.getElementById('labCanvas');
    if (!c) return;
    fitCanvas();
    const ctx = c.getContext('2d');
    const W = c.width, H = c.height;
    ctx.clearRect(0, 0, W, H);
    if (curDim() === 2) draw2D(ctx, W, H); else draw3D(ctx, W, H);
  }

  // ---------------------------------------------------------------------------
  // 2D
  // ---------------------------------------------------------------------------
  function draw2D(ctx, W, H) {
    const lvl = curLevel();
    const P = p => project(p, W, H);
    const S = view.S2;
    // grid
    const G = Math.ceil((W / 2) / S) + 1;
    const step = S >= 30 ? 2 : (S >= 16 ? 5 : 10);
    for (let g = -G; g <= G; g++) {
      const px = P([g, 0, 0])[0], py = P([0, g, 0])[1];
      strokeLine(ctx, [px, 0], [px, H], { color: '#f1f5f9', width: 1 });
      strokeLine(ctx, [0, py], [W, py], { color: '#f1f5f9', width: 1 });
    }
    const o = P([0, 0, 0]);
    strokeLine(ctx, [0, o[1]], [W, o[1]], { color: '#94a3b8', width: 1.8 });
    strokeLine(ctx, [o[0], 0], [o[0], H], { color: '#94a3b8', width: 1.8 });
    for (let g = -Math.floor(G / step) * step; g <= G; g += step) {
      if (g === 0) continue;
      text(ctx, String(g), [P([g, 0, 0])[0] - 5, o[1] + 15], '#64748b', '11px Inter, sans-serif');
      text(ctx, String(g), [o[0] + 6, P([0, g, 0])[1] + 4], '#64748b', '11px Inter, sans-serif');
    }
    // overlays
    overlays().forEach(ov => {
      if (ov.kind === 'all') {
        fillPoly(ctx, [[0, 0], [W, 0], [W, H], [0, H]], ov.color, 0.07);
        text(ctx, ov.label, [14, 22], ov.color);
      } else if (ov.kind === 'line') {
        const ends = lineInBox(ov.dir, 60);
        strokeLine(ctx, P(ends[0]), P(ends[1]), { color: ov.color, width: 7, alpha: 0.28 });
        if (ov.label) { const lp = P(scl(ov.dir, 3.2 / norm(ov.dir))); text(ctx, ov.label, [lp[0] + 10, lp[1] - 10], ov.color, 'bold 14px Inter, sans-serif'); }
      } else if (ov.kind === 'origin') {
        circle(ctx, o, 14, null, ov.color, 3);
      }
    });
    // pool ghosts
    poolGhosts().forEach(g => {
      const a = g.sel ? 1 : 0.35;
      strokeLine(ctx, o, P(g.p), { color: g.color, width: g.sel ? 3 : 2, alpha: a });
      arrowHead(ctx, o, P(g.p), g.color, 10, a);
      text(ctx, g.name, [P(g.p)[0] + 6, P(g.p)[1] - 6], g.color, 'bold 13px Inter, sans-serif', a);
    });
    // target
    if (activePanel === 'basis') drawTarget2D(ctx, P(to3(lvl.target)), lvl);
    // vectors
    const inter = vecsInteractive();
    (st.vecs || []).forEach((v, i) => {
      if (activePanel === 'basis' && st.stage !== 'reach') return;
      const a = P(v.tail), b = P(tipOf(v));
      const alpha = inter ? 1 : 0.55;
      if (isActive(v)) {
        strokeLine(ctx, a, b, { color: v.color, width: 3.6, alpha: alpha });
        arrowHead(ctx, a, b, v.color, 13, alpha);
      }
      circle(ctx, a, 4.5, '#fff', v.color, 2, alpha);
      if (inter) {
        const hv = hover && hover.i === i && hover.part === 'head';
        circle(ctx, b, hv ? 8.5 : 6.5, hv ? v.color : 'rgba(255,255,255,0.85)', v.color, 2.2);
        if (Math.abs(v.c) < 0.15) circle(ctx, P(add(v.tail, scl(v.base, 0.45))), 6, null, v.color, 1.5, 1, [2, 2]);
      }
      text(ctx, `${fmtNum(v.c)}·${v.name}`, [b[0] + 10, b[1] - 8], v.color, 'bold 12px Inter, sans-serif', alpha);
    });
    // current point + marked points
    if (spanBuilding()) {
      const end = currentEnd();
      if (end) circle(ctx, P(end.tip), 11, null, '#0f172a', 1.5, 0.7, [3, 3]);
    }
    markedPoints().forEach(m => {
      const s = P(m.p);
      if (m.anchor) circle(ctx, s, 10, null, SPAN_COLOR, 3);
      const hv = hover && hover.part === 'point' && hover.k === m.k;
      circle(ctx, s, hv ? 7 : 5, '#0f172a', '#fff', 1.5);
      text(ctx, `P${m.k + 1}`, [s[0] + 8, s[1] + 14], '#0f172a', 'bold 11px Inter, sans-serif');
    });
    // origin
    circle(ctx, o, 4, '#0f172a');
  }

  function drawTarget2D(ctx, s, lvl) {
    circle(ctx, s, 9, '#f59e0b', '#b45309', 2);
    circle(ctx, s, 3.5, '#fff');
    text(ctx, `T(${fmtPt(to3(lvl.target))})`, [s[0] + 12, s[1] - 8], '#92400e');
  }

  // ---------------------------------------------------------------------------
  // 3D: painter's algorithm with a semi-opaque floor and a bounding box.
  //   back walls -> far-side items (sorted) -> floor sheet + floor items
  //   -> near-side items (sorted, includes the z-axis) -> labels -> front box edges
  // Lines are cut into short pieces so each piece is sorted by its own depth.
  // ---------------------------------------------------------------------------
  function draw3D(ctx, W, H) {
    const lvl = curLevel();
    const P = p => project(p, W, H);
    const tv = toViewer();
    const depth = p => dot(p, tv);
    const fromAbove = Math.sin(view.pitch) >= 0;
    const isFar = z => fromAbove ? z < -1e-6 : z > 1e-6;
    const far = [], near = [], floor = [], labels = [];
    const push = (p, item) => (isFar(p[2]) ? far : near).push(item);

    // a line segment, cut into pieces (and split where it crosses the floor)
    function seg(a, b, style) {
      const n = Math.max(1, Math.ceil(dist(a, b) / 0.3));
      for (let k = 0; k < n; k++) {
        let p = lerp(a, b, k / n), q = lerp(a, b, (k + 1) / n);
        const parts = [];
        if ((p[2] > 1e-6 && q[2] < -1e-6) || (p[2] < -1e-6 && q[2] > 1e-6)) {
          const m = lerp(p, q, p[2] / (p[2] - q[2]));
          parts.push([p, m], [m, q]);
        } else parts.push([p, q]);
        parts.forEach(pq => {
          const mid = lerp(pq[0], pq[1], 0.5);
          push(mid, { d: depth(mid), f: () => strokeLine(ctx, P(pq[0]), P(pq[1]), style) });
        });
      }
    }
    function arrow3(a, b, color, width, alpha) {
      seg(a, b, { color: color, width: width, alpha: alpha });
      const back = lerp(a, b, Math.max(0, 1 - 0.3 / Math.max(dist(a, b), 1e-6)));
      push(b, { d: depth(b) + 0.001, f: () => arrowHead(ctx, P(back), P(b), color, 13, alpha) });
    }
    function dot3(p, fn) { push(p, { d: depth(p) + 0.002, f: fn }); }
    function label3(p, str, color, dx, dy, font) {
      labels.push({ s: P(p), str: str, color: color, dx: dx || 10, dy: dy || -8, font: font, alpha: isFar(p[2]) ? 0.45 : 1 });
    }

    // ---- bounding box: back walls
    const sideBack = (k, s) => s * tv[k] < 0;
    const boxPt = (k, s, a, ua, b, ub) => { const p = [0, 0, 0]; p[k] = s * BOX; p[a] = ua; p[b] = ub; return p; };
    for (let k = 0; k < 3; k++) for (const s of [-1, 1]) {
      if (!sideBack(k, s)) continue;
      const a = (k + 1) % 3, b = (k + 2) % 3;
      fillPoly(ctx, [[-BOX, -BOX], [BOX, -BOX], [BOX, BOX], [-BOX, BOX]].map(uv => P(boxPt(k, s, a, uv[0], b, uv[1]))), '#e2e8f0', 0.14);
      for (let g = -4; g <= 4; g++) {
        strokeLine(ctx, P(boxPt(k, s, a, g, b, -BOX)), P(boxPt(k, s, a, g, b, BOX)), { color: 'rgba(203,213,225,0.3)', width: 0.7 });
        strokeLine(ctx, P(boxPt(k, s, a, -BOX, b, g)), P(boxPt(k, s, a, BOX, b, g)), { color: 'rgba(203,213,225,0.3)', width: 0.7 });
      }
    }
    function boxEdges(backPass) {
      for (let run = 0; run < 3; run++) {
        const k1 = (run + 1) % 3, k2 = (run + 2) % 3;
        for (const s1 of [-1, 1]) for (const s2 of [-1, 1]) {
          if ((sideBack(k1, s1) && sideBack(k2, s2)) !== backPass) continue;
          const p = [0, 0, 0], q = [0, 0, 0];
          p[k1] = q[k1] = s1 * BOX; p[k2] = q[k2] = s2 * BOX; p[run] = -BOX; q[run] = BOX;
          strokeLine(ctx, P(p), P(q), { color: backPass ? 'rgba(148,163,184,0.35)' : 'rgba(100,116,139,0.45)', width: 1 });
        }
      }
    }
    boxEdges(true);

    // ---- z-axis (sorted with everything else so it can be in front of or behind vectors)
    seg([0, 0, -BOX], [0, 0, BOX], { color: '#0f172a', width: 2.2 });
    const zt = [0, 0, BOX];
    push(zt, { d: depth(zt), f: () => arrowHead(ctx, P([0, 0, BOX - 0.3]), P(zt), '#0f172a', 11) });
    label3(zt, '+Z', '#334155', -10, -10);

    // ---- overlays (V / the group's span)
    overlays().forEach(ov => {
      if (ov.kind === 'line') {
        const ends = lineInBox(ov.dir, BOX);
        seg(ends[0], ends[1], { color: ov.color, width: 7, alpha: 0.3 });
        if (ov.label) label3(scl(ov.dir, 3.4 / norm(ov.dir)), ov.label, ov.color, 10, -10, 'bold 14px Inter, sans-serif');
      } else if (ov.kind === 'plane') {
        // One clean rectangle that fits inside the box. e1 runs along the line where the plane
        // meets the floor (z = 0); e2 climbs up the plane. The rectangle is split along that
        // floor line so the half above the floor and the half below it layer correctly with the
        // semi-opaque floor sheet. Each half is a translucent backdrop drawn first in its layer.
        const n = cross(ov.u, ov.w);
        const horiz = Math.hypot(n[0], n[1]);
        let e1, e2;
        if (horiz < 1e-9) {
          const e = planeBasis(ov.u, ov.w); e1 = e[0]; e2 = e[1];      // the plane IS the floor
        } else {
          e1 = [n[1] / horiz, -n[0] / horiz, 0];                      // horizontal direction in the plane
          e2 = cross(n, e1); e2 = scl(e2, 1 / norm(e2));
          if (e2[2] < 0) e2 = scl(e2, -1);
        }
        const a = BOX / Math.max(...[0, 1, 2].map(k => Math.abs(e1[k]) + Math.abs(e2[k])));
        const pt = (s, t) => add(scl(e1, s * a), scl(e2, t * a));
        const half = (t0, t1) => [pt(-1, t0), pt(1, t0), pt(1, t1), pt(-1, t1)];
        const drawHalf = poly => () => {
          const sp = poly.map(P);
          fillPoly(ctx, sp, ov.color, 0.13);
          ctx.save(); ctx.strokeStyle = ov.color; ctx.globalAlpha = 0.55; ctx.lineWidth = 1.5;
          ctx.beginPath(); sp.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath(); ctx.stroke();
          ctx.restore();
        };
        if (horiz < 1e-9) {
          floor.push(drawHalf(half(-1, 1)));
        } else {
          [[-1, 0], [0, 1]].forEach(tt => {
            const poly = half(tt[0], tt[1]);
            const mid = pt(0, (tt[0] + tt[1]) / 2);
            push(mid, { d: -1e9, f: drawHalf(poly) });
          });
          // the diagonal line where the plane cuts through the x,y floor
          const fl = lineInBox(e1, BOX);
          floor.push(() => strokeLine(ctx, P(fl[0]), P(fl[1]), { color: ov.color, width: 2.5, alpha: 0.85 }));
        }
        if (ov.label) label3(pt(0.55, 0.75), ov.label, ov.color, 8, -8, 'bold 14px Inter, sans-serif');
      } else if (ov.kind === 'origin') {
        floor.push(() => circle(ctx, P([0, 0, 0]), 14, null, ov.color, 3));
      } else if (ov.kind === 'all') {
        // All of R^3: shade the whole box as one translucent solid (a backdrop behind everything)
        const L = BOX - 0.02;
        for (let k = 0; k < 3; k++) for (const s of [-1, 1]) {
          const a = (k + 1) % 3, b = (k + 2) % 3;
          const face = [[-L, -L], [L, -L], [L, L], [-L, L]].map(uv => { const p = [0, 0, 0]; p[k] = s * L; p[a] = uv[0]; p[b] = uv[1]; return P(p); });
          fillPoly(ctx, face, ov.color, 0.07);
          ctx.save(); ctx.strokeStyle = ov.color; ctx.globalAlpha = 0.45; ctx.lineWidth = 1.5;
          ctx.beginPath(); face.forEach((q, i) => i ? ctx.lineTo(q[0], q[1]) : ctx.moveTo(q[0], q[1])); ctx.closePath(); ctx.stroke();
          ctx.restore();
        }
        labels.push({ s: [14, 22], str: ov.label, color: ov.color, dx: 0, dy: 0, alpha: 1, screen: true });
      }
    });

    // ---- pool ghosts (basis: choosing)
    poolGhosts().forEach(g => {
      const a = g.sel ? 1 : 0.35;
      arrow3([0, 0, 0], g.p, g.color, g.sel ? 3 : 2, a);
      label3(g.p, g.name, g.color, 6, -6, 'bold 13px Inter, sans-serif');
    });

    // ---- target
    if (activePanel === 'basis') {
      const t = to3(lvl.target);
      seg([t[0], t[1], 0], t, { color: '#f59e0b', width: 1.4, dash: [3, 3] });
      floor.push(() => circle(ctx, P([t[0], t[1], 0]), 3.5, null, '#f59e0b', 1.5));
      dot3(t, () => { circle(ctx, P(t), 9, '#f59e0b', '#b45309', 2); circle(ctx, P(t), 3.5, '#fff'); });
      label3(t, `T(${fmtPt(t, 3)})`, '#92400e', 12, -8);
    }

    // ---- vectors
    const inter = vecsInteractive();
    const showVecs = activePanel === 'span' || st.stage === 'reach';
    if (showVecs) (st.vecs || []).forEach((v, i) => {
      const tail = v.tail, tip = tipOf(v);
      const alpha = inter ? 1 : 0.55;
      const xyT = [tail[0], tail[1], 0], xyH = [tip[0], tip[1], 0];
      // floor shadow + floor ring (lie on the floor)
      floor.push(() => {
        strokeLine(ctx, P(xyT), P(xyH), { color: v.color + '77', width: 2.2, dash: [5, 5] });
        arrowHead(ctx, P(xyT), P(xyH), v.color + '77', 10);
        if (inter) {
          const hv = hover && hover.i === i && hover.part === 'xy';
          circle(ctx, P(xyH), hv ? 8 : 6.5, '#fff', v.color, hv ? 3.5 : 2.5);
        }
      });
      // drop lines from the floor to tail / tip
      if (Math.abs(tail[2]) > 0.02) seg(xyT, tail, { color: v.color + '88', width: 1.5, dash: [3, 3] });
      if (Math.abs(tip[2]) > 0.02) seg(xyH, tip, { color: v.color + '88', width: 1.5, dash: [3, 3] });
      // the vector itself
      if (isActive(v)) arrow3(tail, tip, v.color, 3.6, alpha);
      dot3(tail, () => circle(ctx, P(tail), 4.5, '#fff', v.color, 2, alpha));
      if (inter) {
        dot3(tip, () => {
          const hv = hover && hover.i === i && hover.part === 'head';
          circle(ctx, P(tip), hv ? 8.5 : 6.5, hv ? v.color : 'rgba(255,255,255,0.85)', v.color, 2.2);
        });
        if (Math.abs(v.c) < 0.15) { const g = add(tail, scl(v.base, 0.45)); dot3(g, () => circle(ctx, P(g), 6, null, v.color, 1.5, 1, [2, 2])); }
      }
      label3(tip, `${fmtNum(v.c)}·${v.name}`, v.color);
    });

    // ---- current point & marked points
    if (spanBuilding()) {
      const end = currentEnd();
      if (end) dot3(end.tip, () => circle(ctx, P(end.tip), 11, null, '#0f172a', 1.5, 0.7, [3, 3]));
    }
    markedPoints().forEach(m => {
      const fl = [m.p[0], m.p[1], 0];
      if (Math.abs(m.p[2]) > 0.02) seg(fl, m.p, { color: '#475569', width: 1.2, dash: [2, 3] });
      floor.push(() => circle(ctx, P(fl), 2.5, '#94a3b8'));
      dot3(m.p, () => {
        if (m.anchor) circle(ctx, P(m.p), 10, null, SPAN_COLOR, 3);
        const hv = hover && hover.part === 'point' && hover.k === m.k;
        circle(ctx, P(m.p), hv ? 7 : 5, '#0f172a', '#fff', 1.5);
      });
      label3(m.p, `P${m.k + 1}`, '#0f172a', 8, 14, 'bold 11px Inter, sans-serif');
    });

    // ---- paint: far side, floor, near side
    far.sort((a, b) => a.d - b.d).forEach(it => it.f());
    const fc = [[-BOX, -BOX, 0], [BOX, -BOX, 0], [BOX, BOX, 0], [-BOX, BOX, 0]].map(P);
    fillPoly(ctx, fc, '#f1f5f9', 0.82);
    ctx.save(); ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 1.2; ctx.beginPath();
    fc.forEach((c, i) => i ? ctx.lineTo(c[0], c[1]) : ctx.moveTo(c[0], c[1])); ctx.closePath(); ctx.stroke(); ctx.restore();
    for (let g = -4; g <= 4; g++) {
      strokeLine(ctx, P([g, -BOX, 0]), P([g, BOX, 0]), { color: '#d5dde7', width: 1 });
      strokeLine(ctx, P([-BOX, g, 0]), P([BOX, g, 0]), { color: '#d5dde7', width: 1 });
    }
    // x and y axes lie in the floor
    strokeLine(ctx, P([-BOX, 0, 0]), P([BOX, 0, 0]), { color: '#64748b', width: 1.8 });
    arrowHead(ctx, P([BOX - 0.3, 0, 0]), P([BOX, 0, 0]), '#64748b', 10);
    strokeLine(ctx, P([0, -BOX, 0]), P([0, BOX, 0]), { color: '#64748b', width: 1.8 });
    arrowHead(ctx, P([0, BOX - 0.3, 0]), P([0, BOX, 0]), '#64748b', 10);
    floor.forEach(f => f());
    circle(ctx, P([0, 0, 0]), 4, '#0f172a');
    near.sort((a, b) => a.d - b.d).forEach(it => it.f());

    // ---- labels on top
    label3([BOX, 0, 0], '+X', '#334155', 6, 4);
    label3([0, BOX, 0], '+Y', '#334155', 6, 4);
    labels.forEach(l => text(ctx, l.str, l.screen ? l.s : [l.s[0] + l.dx, l.s[1] + l.dy], l.color, l.font, l.alpha));
    boxEdges(false);
  }

  // ===========================================================================
  // INTERACTION
  // ===========================================================================
  function mousePos(e, c) {
    const r = c.getBoundingClientRect();
    return [(e.clientX - r.left) * (c.width / r.width), (e.clientY - r.top) * (c.height / r.height)];
  }
  function zPerPixel() { return 1 / (view.S3 * Math.max(0.15, Math.cos(view.pitch))); }

  function segDist(p, a, b) {
    const l2 = (b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2;
    if (l2 === 0) return Math.hypot(p[0] - a[0], p[1] - a[1]);
    const t = Math.max(0, Math.min(0.85, ((p[0] - a[0]) * (b[0] - a[0]) + (p[1] - a[1]) * (b[1] - a[1])) / l2));
    return Math.hypot(p[0] - (a[0] + t * (b[0] - a[0])), p[1] - (a[1] + t * (b[1] - a[1])));
  }

  function hitTest(mx, my, W, H) {
    const P = p => project(p, W, H);
    const d3 = curDim() === 3;
    let best = null, bd = Infinity;
    const consider = (d, r, h) => { if (d <= r && d < bd) { bd = d; best = h; } };

    if (activePanel === 'span' && st.stage === 'place' && anchorsNeeded(st.shape) > 0) {
      st.marked.forEach((m, k) => { const s = P(m.p); consider(Math.hypot(mx - s[0], my - s[1]), 13, { part: 'point', k: k }); });
      return best;
    }
    if (!vecsInteractive()) return null;
    st.vecs.forEach((v, i) => {
      const tip = tipOf(v), ts = P(tip), as = P(v.tail);
      const headR = Math.max(10, Math.min(20, 0.3 * Math.hypot(ts[0] - as[0], ts[1] - as[1])));
      consider(Math.hypot(mx - ts[0], my - ts[1]), headR, { i: i, part: 'head' });
      if (d3) { const fs = P([tip[0], tip[1], 0]); consider(Math.hypot(mx - fs[0], my - fs[1]) + 4, 18, { i: i, part: 'xy' }); }
      if (Math.abs(v.c) < 0.15) { const g = P(add(v.tail, scl(v.base, 0.45))); consider(Math.hypot(mx - g[0], my - g[1]), 16, { i: i, part: 'head' }); }
    });
    if (best) return best;
    st.vecs.forEach((v, i) => {
      const tip = tipOf(v);
      if (isActive(v)) consider(segDist([mx, my], P(v.tail), P(tip)), 14, { i: i, part: 'shaft' });
      if (d3) consider(segDist([mx, my], P([v.tail[0], v.tail[1], 0]), P([tip[0], tip[1], 0])) + 2, 13, { i: i, part: 'xyshaft' });
    });
    return best;
  }

  function snapScalar(c) {
    c = Math.max(-4, Math.min(4, c));
    if (Math.abs(c) < 0.09) return 0;
    const q = Math.round(c * 4) / 4;
    if (Math.abs(c - q) < 0.09) return q;
    return Math.round(c * 20) / 20;
  }

  function onDown(e) {
    const c = document.getElementById('labCanvas');
    if (!c) return;
    const [mx, my] = mousePos(e, c);
    const h = hitTest(mx, my, c.width, c.height);
    if (h && h.part === 'point') {
      // pin / unpin a marked point as an anchor of the group's line or plane
      const need = anchorsNeeded(st.shape);
      if (st.anchors.includes(h.k)) st.anchors = st.anchors.filter(k => k !== h.k);
      else { st.anchors.push(h.k); if (st.anchors.length > need) st.anchors.shift(); }
      st.msg = null;
      renderSide(); draw();
      return;
    }
    if (h) {
      const v = st.vecs[h.i];
      drag = { part: h.part, i: h.i, start: [mx, my], startC: v.c, startTail: v.tail.slice() };
    } else if (curDim() === 3) {
      drag = { part: 'camera', last: [mx, my] };
      c.style.cursor = 'grabbing';
    }
  }

  function onMove(e) {
    const c = document.getElementById('labCanvas');
    if (!c) return;
    const [mx, my] = mousePos(e, c);
    const W = c.width, H = c.height;
    if (!drag) {
      const h = hitTest(mx, my, W, H);
      c.style.cursor = h ? 'pointer' : (curDim() === 3 ? 'grab' : 'default');
      if (JSON.stringify(h) !== JSON.stringify(hover)) { hover = h; draw(); }
      return;
    }
    if (drag.part === 'camera') {
      const dx = mx - drag.last[0], dy = my - drag.last[1];
      drag.last = [mx, my];
      view.yaw += dx * 0.01;                       // drag right -> xy-plane turns counterclockwise
      view.pitch = Math.max(-1.45, Math.min(1.45, view.pitch + dy * 0.01));
      draw();
      return;
    }
    const v = st.vecs[drag.i];
    const d3 = curDim() === 3;
    if (drag.part === 'head') {
      // ARROWHEAD: stretch the vector (change λ) along its own line
      const p0 = project(v.tail, W, H);
      const p1 = project(add(v.tail, v.base), W, H);
      const vx = p1[0] - p0[0], vy = p1[1] - p0[1], len2 = vx * vx + vy * vy;
      if (len2 > 64) v.c = snapScalar(((mx - p0[0]) * vx + (my - p0[1]) * vy) / len2);
      else if (d3 && Math.abs(v.base[2]) > 0.05) v.c = snapScalar(drag.startC + (drag.start[1] - my) * zPerPixel() / v.base[2]);
    } else {
      // move the whole vector (its tail)
      let cand;
      const dx = mx - drag.start[0], dy = my - drag.start[1];
      if (!d3) {
        cand = [drag.startTail[0] + dx / view.S2, drag.startTail[1] - dy / view.S2, 0];
        cand = cand.map(x => Math.max(-view.lim, Math.min(view.lim, x)));
      } else if (drag.part === 'shaft') {
        // SHAFT (3D): move straight up/down in z only
        cand = [drag.startTail[0], drag.startTail[1], drag.startTail[2] - dy * zPerPixel()];
      } else {
        // FLOOR CIRCLE or dashed FLOOR SHADOW (3D): slide in x and y, keeping the same height
        const a = unprojectFloor(drag.start[0], drag.start[1], 0, W, H), b = unprojectFloor(mx, my, 0, W, H);
        cand = [drag.startTail[0] + b[0] - a[0], drag.startTail[1] + b[1] - a[1], drag.startTail[2]];
      }
      if (d3) cand = cand.map(x => Math.max(-BOX, Math.min(BOX, x)));
      // snap the tail onto the origin or another vector's tip
      const targets = [[0, 0, 0]];
      st.vecs.forEach((o, j) => { if (j !== drag.i && isActive(o)) targets.push(tipOf(o)); });
      const cs = project(cand, W, H);
      let snapped = null;
      for (const t of targets) {
        const ts = project(t, W, H);
        if (dist(cand, t) <= 0.42 || Math.hypot(cs[0] - ts[0], cs[1] - ts[1]) <= 22) { snapped = t.slice(); break; }
      }
      v.tail = snapped || cand.map(x => Math.round(x * 4) / 4);
    }
    updateLive();
    draw();
  }

  function onUp() {
    if (!drag) return;
    drag = null;
    const c = document.getElementById('labCanvas');
    if (c) c.style.cursor = '';
    draw();
  }

  function zoom(f) {
    if (curDim() === 3) view.S3 = Math.max(18, Math.min(110, view.S3 * f));
    else { view.S2 = Math.max(12, Math.min(110, view.S2 * f)); syncLim(); }
    draw();
  }

  // ===========================================================================
  // MOUNTING
  // ===========================================================================
  function mount(panel) {
    ['span', 'basis'].forEach(p => {
      const m = document.getElementById('mount-' + p);
      if (m && p !== panel) m.innerHTML = '';
    });
    const m = document.getElementById('mount-' + panel);
    if (!m) return;
    m.innerHTML = workspaceHTML;
    const c = document.getElementById('labCanvas');
    c.addEventListener('pointerdown', onDown);
    c.addEventListener('wheel', e => { e.preventDefault(); zoom(e.deltaY < 0 ? 1.12 : 1 / 1.12); }, { passive: false });
    document.getElementById('btnZoomIn').onclick = () => zoom(1.25);
    document.getElementById('btnZoomOut').onclick = () => zoom(1 / 1.25);
    document.getElementById('btnZoomReset').onclick = () => { setDefaultView(); draw(); };
    loadLevel(panel, activeIdx[panel]);
  }

  window.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup', onUp);
  window.addEventListener('resize', () => draw());

  document.addEventListener('shown.bs.tab', e => {
    const v = e.target.getAttribute('data-value');
    if (v === 'span' || v === 'basis') mount(v);
    if (v === 'notes') renderNotes();
  });
  document.addEventListener('DOMContentLoaded', () => setTimeout(() => { mount('span'); renderNotes(); }, 80));

  if (window.Shiny && Shiny.addCustomMessageHandler) {
    Shiny.addCustomMessageHandler('groupInfo', msg => {
      group.names = [].concat(msg.names || []);
      group.plans = msg.plans || '';
      const b = document.getElementById('groupBanner');
      if (b) b.textContent = 'Group: ' + group.names.join(', ');
      if (document.getElementById('sideCard')) renderSide();
      pushNotes();
      // the popup has just been closed; make sure it did not leave the page scroll-locked
      setTimeout(unlockScroll, 400);
      setTimeout(unlockScroll, 1200);
    });
  }

  // Bootstrap locks page scrolling while a popup is open (overflow: hidden on <body>).
  // Re-showing the check-in popup to display an error can leave that lock behind after it
  // closes, so clear it whenever no popup is actually open.
  function unlockScroll() {
    if (document.querySelector('.modal.show')) return;
    document.body.classList.remove('modal-open');
    document.body.style.overflow = '';
    document.body.style.paddingRight = '';
    document.querySelectorAll('.modal-backdrop').forEach(b => b.remove());
  }
  document.addEventListener('hidden.bs.modal', () => setTimeout(unlockScroll, 50));
})();
)---"

checkin_modal <- function(err = NULL, names = "", plans = "") {
  modalDialog(
    title = "Before you start: group check-in",
    tags$p("You'll work through this lab as a group, talking things out as you go. Start by introducing yourselves."),
    textInput("ci_names", "Group members' names (separate with commas)", value = names,
              placeholder = "First name, First name, First name", width = "100%"),
    textAreaInput("ci_plans",
                  "Go around the group: what is everyone doing this weekend, or looking forward to? (Each person shares one thing.)",
                  value = plans, rows = 4, width = "100%",
                  placeholder = "Person 1: ...\nPerson 2: ...\nPerson 3: ..."),
    if (!is.null(err)) div(class = "text-danger fw-semibold", err),
    footer = actionButton("ci_go", "Let's start", class = "btn-primary"),
    easyClose = FALSE,
    size = "m"
  )
}

ui <- page_navbar(
  title = "Span & Bases Lab",
  fillable = FALSE,   # let the page scroll normally (fillable layouts lock the page to the window height)
  theme = bs_theme(version = 5, bootswatch = "flatly", primary = "#1e293b"),
  header = tags$head(tags$style(HTML(lab_css))),
  nav_panel(title = "Start Here", value = "start",
            div(class = "start-wrap",
                div(class = "start-card",
                    h4("Quick recap from lecture: span and basis"),
                    p("Before the lab, here are the ideas from today's lecture you'll be using. Skim it as a group, then start Panel 1.")),
                div(class = "start-card",
                    h4("1. Span"),
                    p(HTML("A <strong>vector subspace</strong> is the set of all points that can be reached by stretching and combining a collection of vectors. We say the collection of vectors <strong>span</strong> the subspace.")),
                    div(class = "big-def", HTML("<strong>Span:</strong> span({<strong>v<sub>1</sub></strong>, &hellip;, <strong>v<sub>n</sub></strong>}) = { &lambda;<sub>1</sub><strong>v<sub>1</sub></strong> + &hellip; + &lambda;<sub>n</sub><strong>v<sub>n</sub></strong> : &lambda; &isin; &#8477; }")),
                    tags$ul(
                      tags$li(HTML("What are the vectors doing? <strong>Spanning.</strong> What are the vectors spanning? <strong>A subspace.</strong>")),
                      tags$li(HTML("Example: <span class='eg'><strong>a</strong> = (1, 0)</span> and <span class='eg'><strong>b</strong> = (0, 1)</span> span V = { &lambda;<sub>1</sub><strong>a</strong> + &lambda;<sub>2</sub><strong>b</strong> } = &#8477;<sup>2</sup>.")),
                      tags$li(HTML("Is a vector <strong>in the span</strong>? To show &ldquo;yes,&rdquo; find the linear combination. To show &ldquo;no,&rdquo; prove no linear combination exists."))
                    ),
                    p(tags$strong("In Panel 1"), "you build points from a collection of vectors, then decide what their span looks like.")),
                div(class = "start-card",
                    h4("2. Basis"),
                    div(class = "big-def", HTML("<strong>Basis:</strong> a collection of <em>n</em>-dimensional vectors <strong>v<sub>1</sub></strong>, &hellip;, <strong>v<sub>m</sub></strong> forms a basis for some subspace in &#8477;<sup><em>n</em></sup> if<br>1. the collection <strong>spans that entire subspace</strong>, and<br>2. the collection is <strong>linearly independent</strong>.")),
                    p(HTML("The basis is essentially the &ldquo;measurement&rdquo; or coordinate system for the subspace.")),
                    tags$ul(
                      tags$li(HTML("A basis does <strong>not</strong> need to span the entire ambient space &#8477;<sup><em>n</em></sup>, just a particular subspace. Example: <span class='eg'>{(1, 0)}</span> is a basis for V = {(<em>x</em>, 0)}, a one-dimensional subspace of &#8477;<sup>2</sup>.")),
                      tags$li(HTML("Bases are <strong>not unique</strong>. Both <span class='eg'>{(1, 0), (0, 1)}</span> and <span class='eg'>{(1, 1), (0, 1)}</span> are bases for &#8477;<sup>2</sup>.")),
