server <- function(input, output, session) {
  showModal(checkin_modal())

  observeEvent(input$ci_go, {
    raw_names <- input$ci_names %||% ""
    plans <- trimws(input$ci_plans %||% "")
    nm <- trimws(unlist(strsplit(raw_names, "[,;\n]+|\\s+and\\s+")))
    nm <- nm[nzchar(nm)]
    if (length(nm) < 2) {
      showModal(checkin_modal("List everyone in your group (at least 2 names, separated by commas).", raw_names, plans))
      return()
    }
    if (nchar(plans) < 20) {
      showModal(checkin_modal("Tell each other a bit more: every person shares one thing they're doing or looking forward to.", raw_names, plans))
      return()
    }
    removeModal()
    session$sendCustomMessage("groupInfo", list(names = as.list(nm), plans = plans))
  })

  notes <- reactiveVal(NULL)
  observeEvent(input$notes_json, {
    notes(jsonlite::fromJSON(input$notes_json))
  })

  output$dl_notes <- downloadHandler(
    filename = function() paste0("Lecture20_group_notes_", format(Sys.time(), "%Y-%m-%d_%H%M"), ".csv"),
    content = function(file) {
      n <- notes()
      group_names <- if (is.null(n)) "" else paste(n$names, collapse = ", ")
      plans <- if (is.null(n)) "" else n$plans
      rows <- if (!is.null(n) && length(n$notes) > 0 && NROW(n$notes) > 0) as.data.frame(n$notes) else
        data.frame(panel = character(), level = character(), prediction = character(),
                   question = character(), answer = character(), time = character())
      out <- rbind(
        data.frame(group = group_names, weekend_plans = plans, panel = "Check-in", level = "",
                   prediction = "", question = "", answer = "", time = ""),
        if (nrow(rows) > 0) data.frame(group = group_names, weekend_plans = "", rows[, c("panel", "level", "prediction", "question", "answer", "time")])
      )
      write.csv(out, file, row.names = FALSE)
    }
  )
}

shinyApp(ui, server)
